 res=[row[:] for row in grid]
 for r in range(h):
  pos=[c for c,v in enumerate(grid[r]) if v!=bg]
  for a,b in zip(pos,pos[1:]):
   if b-a<=maxdist:
    for c in range(a+1,b):
     if grid[r][c]==bg:res[r][c]=2
 for c in range(w):
  pos=[r for r in range(h) if grid[r][c]!=bg]
  for a,b in zip(pos,pos[1:]):
