def heuristic(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 anchors=lambda r,c:grid[r][c]!=bg
 strongH={}; strongV={}
 # perpendicular membership: endpoint of a horizontal gap is strong if it lies in a compact vertical group, and vice versa
 for r in range(h):
  for c in range(w):
   if anchors(r,c):
    strongH[r,c]=any(0<abs(rr-r)<=3 and anchors(rr,c) for rr in range(h))
    strongV[r,c]=any(0<abs(cc-c)<=3 and anchors(r,cc) for cc in range(w))
 res=[row[:] for row in grid]
 # fill gaps
 for r in range(h):
  ps=[c for c in range(w) if anchors(r,c)]
  for a,b in zip(ps,ps[1:]):
   if b-a<=3 or (b-a<=7 and not(strongH[r,a] and strongH[r,b])):
    for c in range(a+1,b): res[r][c]=2
 for c in range(w):
  ps=[r for r in range(h) if anchors(r,c)]
  for a,b in zip(ps,ps[1:]):
   if b-a<=3 or (b-a<=7 and not(strongV[a,c] and strongV[b,c])):
    for r in range(a+1,b):res[r][c]=2
 # build filled non-bg connected intervals of at least two original anchors, then connect close perpendicular segment endpoints
 hs=[]; vs=[]
 for r in range(h):
  ps=[c for c in range(w) if anchors(r,c)]
  groups=[]
  for c in ps:
   if not groups or c-groups[-1][-1]>1 and res[r][groups[-1][-1]+1]!=2:
    groups.append([c])
   else: groups[-1].append(c)
  # simpler: derive intervals of non-bg cells in res and require >=2 original markers
  c=0
  while c<w:
   if res[r][c]!=bg:
    s=c
    while c<w and res[r][c]!=bg:c+=1
    if sum(anchors(r,j) for j in range(s,c))>=2: hs.append((r,s,c-1))
   else:c+=1
 for c in range(w):
  r=0
  while r<h:
   if res[r][c]!=bg:
    s=r
    while r<h and res[r][c]!=bg:r+=1
    if sum(anchors(i,c) for i in range(s,r))>=2:vs.append((c,s,r-1))
   else:r+=1
 # connector using nearest endpoints of each orthogonal pair, if path has max Manhattan 5 and doesn't already overlap
 for c,rs,re in vs:
  for r,cs,ce in hs:
   vr=min(max(r,rs),re); hc=min(max(c,cs),ce)
   dist=abs(r-vr)+abs(c-hc)
   if dist<=5 and dist>0:
    # extend vertical then horizontal to the other segment
    for rr in range(min(vr,r),max(vr,r)+1):
     if res[rr][c]==bg:res[rr][c]=2
    for cc in range(min(c,hc),max(c,hc)+1):
     if res[r][cc]==bg:res[r][cc]=2
 return res
